import { htmlShell, SITE } from "./shell";

export const CANNABIS_AUTHOR =
  "Jeremy Mills, CEO & Founder, Apex Grid Engineering — USAF Veteran";

type Link = { label: string; href: string };
type Faq = { question: string; answer: string };

/**
 * Cannabis cultivation facility design pages: one national hub, one hub per
 * licensed jurisdiction (49 states + DC), and city pages for real cultivation
 * markets. Rendered as static HTML by seo/generate.ts and registered in
 * sitemap-cannabis.xml.
 */
export interface CannabisFacilityPage {
  segments: string[];
  title: string;
  description: string;
  h1: string;
  kicker: string;
  intro: string;
  perspective: string;
  topics: string[];
  links: Link[];
  faqs: Faq[];
}

export function cannabisUrl(page: CannabisFacilityPage): string {
  return `/cannabis-facility-design/${page.segments.join("/")}${page.segments.length ? "/" : ""}`;
}

const esc = (value: string) =>
  value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const titleCase = (value: string) =>
  value.replace(/-/g, " ").replace(/\b\w/g, (char) => char.toUpperCase());

export function cannabisPage(page: CannabisFacilityPage): string {
  const url = cannabisUrl(page);
  const crumbs = [
    { name: "Home", href: "/" },
    { name: "Cannabis Facility Design", href: "/cannabis-facility-design/" },
    ...(page.segments.length > 0
      ? [{ name: titleCase(page.segments[0]), href: `/cannabis-facility-design/${page.segments[0]}/` }]
      : []),
    ...(page.segments.length > 1 ? [{ name: titleCase(page.segments[1]) }] : []),
    ...(page.segments.length === 0 ? [{ name: "National Hub" }] : []),
  ];
  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: page.faqs.map((faq) => ({
      "@type": "Question",
      name: faq.question,
      acceptedAnswer: { "@type": "Answer", text: faq.answer },
    })),
  };
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((crumb, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: crumb.name,
      ...("href" in crumb && crumb.href ? { item: `${SITE}${crumb.href}` } : {}),
    })),
  };
  const serviceSchema = {
    "@context": "https://schema.org",
    "@type": "Service",
    name: page.h1,
    description: page.description,
    provider: { "@type": "Organization", name: "Apex Grid Engineering", url: SITE },
    url: `${SITE}${url}`,
    areaServed: { "@type": "Country", name: "United States" },
  };
  const body = `
<nav class="breadcrumb">${crumbs.map((crumb) => "href" in crumb && crumb.href ? `<a href="${crumb.href}">${esc(crumb.name)}</a><span>/</span>` : `<b>${esc(crumb.name)}</b>`).join("")}</nav>
<section class="hero"><div class="container"><p class="kicker">${esc(page.kicker)}</p><h1>${esc(page.h1)}</h1><p class="lede">${esc(page.intro)}</p><p class="byline">By ${CANNABIS_AUTHOR}</p></div></section>
<section class="block prose"><div class="container"><h2>How I approach <em>cultivation facility engineering</em></h2><p>${esc(page.perspective)}</p><p>A cultivation facility is a process building first and a real-estate project second. I confirm the license type, canopy plan, cultivation method, and the authority having jurisdiction before treating any layout as final, because the mechanical and electrical systems are sized from the plants outward - not from the building inward.</p><p>Licensing timelines drive everything in this sector. I sequence engineering deliverables to match application and inspection milestones so operators are never waiting on drawings while a license window closes.</p></div></section>
<section class="block"><div class="container"><h2>Cultivation <em>engineering scope</em></h2><ul class="scope">${page.topics.map((topic) => `<li>${esc(topic)}</li>`).join("")}</ul></div></section>
<section class="block recommended-resources"><div class="container"><h2>Related <em>resources and services</em></h2><ul>${page.links.map((link) => `<li><a href="${link.href}">${esc(link.label)}</a></li>`).join("")}</ul></div></section>
<section class="block faq"><div class="container"><h2>Frequently Asked <em>Questions</em></h2><div class="faq">${page.faqs.map((faq) => `<details><summary>${esc(faq.question)}</summary><div class="a">${esc(faq.answer)}</div></details>`).join("")}</div></div></section>
<section class="ctaband"><div class="container"><h2>Engineer your facility before the license window closes</h2><p>Send your site, canopy plan, and target license date. I will scope the MEP, structural, and permit package your application actually requires.</p><a class="cta" href="/estimate/">Request an Estimate</a></div></section>`;
  return htmlShell({ title: page.title, description: page.description, canonical: `${SITE}${url}`, schemaJson: [serviceSchema, breadcrumbSchema, faqSchema], body });
}

